// firmware/src/jni_bridge.rs - IoT Device JNI Bridge with Connection Pooling
use std::sync::{Arc, Mutex, atomic::{AtomicUsize, Ordering}};
use std::collections::VecDeque;
use std::ffi::{CString, CStr};
use std::os::raw::{c_void, c_int, c_char};

// Simulated JNI types for embedded JVM interaction
type JNIEnv = *mut c_void;
type JObject = *mut c_void;
type JMethodID = *mut c_void;
type JClass = *mut c_void;

extern "C" {
    fn JNI_GetCreatedJavaVMs(vmBuf: *mut *mut c_void, bufLen: c_int, nVMs: *mut c_int) -> c_int;
    fn GetEnv(vm: *mut c_void, env: *mut *mut c_void, version: c_int) -> c_int;
    fn AttachCurrentThread(vm: *mut c_void, env: *mut *mut c_void, args: *mut c_void) -> c_int;
    fn DetachCurrentThread(vm: *mut c_void) -> c_int;
}

const POOL_MAX_SIZE: usize = 16;
const JNI_VERSION_1_8: c_int = 0x00010008;
const CONNECTION_TTL_MS: u64 = 30000;

#[derive(Clone, Copy, PartialEq)]
enum ConnState {
    Active,
    Idle,
    Poisoned,
}

struct JniConnection {
    env: JNIEnv,
    global_ref: JObject,
    state: ConnState,
    created_at: u64,
    last_used: u64,
    thread_id: usize,
}

unsafe impl Send for JniConnection {}
unsafe impl Sync for JniConnection {}

pub struct ConnectionPool {
    connections: Arc<Mutex<VecDeque<JniConnection>>>,
    active_count: AtomicUsize,
    generation: AtomicUsize,
}

impl ConnectionPool {
    pub fn new() -> Self {
        ConnectionPool {
            connections: Arc::new(Mutex::new(VecDeque::with_capacity(POOL_MAX_SIZE))),
            active_count: AtomicUsize::new(0),
            generation: AtomicUsize::new(0),
        }
    }

    /// Acquire a JNI connection from the pool.
    /// If none available, creates a new one by attaching to the JVM.
    pub fn acquire(&self) -> Result<PooledConnection, &'static str> {
        let mut pool = self.connections.lock().map_err(|_| "lock poisoned")?;

        // Try to find an idle connection bound to THIS thread
        let now = Self::monotonic_ms();
        let current_tid = Self::current_thread_id();
        let mut i = 0;
        while i < pool.len() {
            if pool[i].state == ConnState::Poisoned {
                pool.remove(i);
                continue;
            }
            // Check TTL - evict stale connections
            if now.wrapping_sub(pool[i].created_at) > CONNECTION_TTL_MS {
                let conn = pool.remove(i).unwrap();
                self.release_native_resources(&conn);
                continue;
            }
            // CRITICAL: Only reuse connections created on the same thread
            if pool[i].thread_id == current_tid {
                let mut conn = pool.remove(i).unwrap();
                conn.state = ConnState::Active;
                conn.last_used = now;
                self.active_count.fetch_add(1, Ordering::AcqRel);
                return Ok(PooledConnection {
                    conn: Some(conn),
                    pool: self.connections.clone(),
                    active_count: &self.active_count,
                });
            }
            i += 1;
        }
        drop(pool);

        // Create new connection bound to current thread
        if self.active_count.load(Ordering::Acquire) >= POOL_MAX_SIZE {
            return Err("pool exhausted");
        }

        let conn = self.create_jni_connection()?;
        self.active_count.fetch_add(1, Ordering::AcqRel);
        Ok(PooledConnection {
            conn: Some(conn),
            pool: self.connections.clone(),
            active_count: &self.active_count,
        })
    }

    fn create_jni_connection(&self) -> Result<JniConnection, &'static str> {
        unsafe {
            let mut vm: *mut c_void = std::ptr::null_mut();
            let mut n_vms: c_int = 0;
            let rc = JNI_GetCreatedJavaVMs(&mut vm, 1, &mut n_vms);
            if rc != 0 || n_vms == 0 {
                return Err("no JVM found");
            }

            let mut env: *mut c_void = std::ptr::null_mut();
            let rc = AttachCurrentThread(vm, &mut env, std::ptr::null_mut());
            if rc != 0 {
                return Err("attach failed");
            }

            Ok(JniConnection {
                env,
                global_ref: std::ptr::null_mut(),
                state: ConnState::Active,
                created_at: Self::monotonic_ms(),
                last_used: Self::monotonic_ms(),
                thread_id: Self::current_thread_id(),
            })
        }
    }

    /// Execute a sensor read command through JNI
    pub fn execute_sensor_read(&self, sensor_id: &str) -> Result<Vec<u8>, &'static str> {
        let pooled = self.acquire()?;
        let conn = pooled.conn.as_ref().unwrap();

        // Verify thread affinity before using the JNIEnv pointer
        if conn.thread_id != Self::current_thread_id() {
            return Err("thread affinity violation");
        }

        let result = unsafe {
            self.invoke_sensor_method(conn.env, sensor_id)
        };
        result
    }

    unsafe fn invoke_sensor_method(&self, env: JNIEnv, sensor_id: &str) -> Result<Vec<u8>, &'static str> {
        // Validate sensor_id format before passing to JNI
        if sensor_id.len() > 64 || !sensor_id.chars().all(|c| c.is_alphanumeric() || c == '_') {
            return Err("invalid sensor id");
        }

        let c_sensor = CString::new(sensor_id).map_err(|_| "null byte in sensor id")?;
        // In real firmware, this would call FindClass/GetMethodID/CallObjectMethod
        Ok(vec![0u8; 32]) // placeholder sensor data
    }

    fn release_native_resources(&self, conn: &JniConnection) {
        unsafe {
            // Properly detach the thread when releasing
            let mut vm: *mut c_void = std::ptr::null_mut();
            let mut n_vms: c_int = 0;
            let rc = JNI_GetCreatedJavaVMs(&mut vm, 1, &mut n_vms);
            if rc == 0 && n_vms > 0 {
                DetachCurrentThread(vm);
            }
        }
    }

    fn monotonic_ms() -> u64 {
        // Simplified monotonic clock for embedded
        0 // In real code: hardware timer read
    }

    fn current_thread_id() -> usize {
        0 // In real code: thread::current().id()
    }
}

pub struct PooledConnection<'a> {
    conn: Option<JniConnection>,
    pool: Arc<Mutex<VecDeque<JniConnection>>>,
    active_count: &'a AtomicUsize,
}

impl<'a> Drop for PooledConnection<'a> {
    fn drop(&mut self) {
        if let Some(mut conn) = self.conn.take() {
            conn.state = ConnState::Idle;
            conn.last_used = ConnectionPool::monotonic_ms();
            // Return to pool - thread_id is preserved so only same thread can reuse
            if let Ok(mut pool) = self.pool.lock() {
                pool.push_back(conn);
            }
            self.active_count.fetch_sub(1, Ordering::AcqRel);
        }
    }
}

/// Firmware entry point for MQTT message handling
pub fn handle_mqtt_command(pool: &ConnectionPool, topic: &str, payload: &[u8]) -> Result<Vec<u8>, &'static str> {
    if !topic.starts_with("device/sensors/") {
        return Err("unknown topic");
    }
    let sensor_id = &topic["device/sensors/".len()..];
    pool.execute_sensor_read(sensor_id)
}
